func (q *Queries) UpsertRemote(ctx context.Context, arg UpsertRemoteParams) (Remote, error) {
	row := q.db.QueryRow(ctx, upsertRemote,
		arg.RepoID,
		arg.UpstreamUrl,
		arg.CredentialsRef,
		arg.TtlSeconds,
		arg.NegativeTtlSeconds,
	)
	var i Remote
	err := row.Scan(
		&i.RepoID,
		&i.UpstreamUrl,
		&i.CredentialsRef,
		&i.TtlSeconds,
		&i.NegativeTtlSeconds,
	)
	return i, err
}

const upsertRemoteCache = `-- name: UpsertRemoteCache :one
INSERT INTO remote_cache (repo_id, cache_key, status, blob_digest, fetched_at)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (repo_id, cache_key) DO UPDATE
SET status = EXCLUDED.status,
    blob_digest = EXCLUDED.blob_digest,
    fetched_at = EXCLUDED.fetched_at
RETURNING repo_id, cache_key, status, blob_digest, fetched_at
`

type UpsertRemoteCacheParams struct {
	RepoID     uuid.UUID   `json:"repo_id"`
	CacheKey   string      `json:"cache_key"`
	Status     string      `json:"status"`
	BlobDigest pgtype.Text `json:"blob_digest"`
	FetchedAt  time.Time   `json:"fetched_at"`
}

func (q *Queries) UpsertRemoteCache(ctx context.Context, arg UpsertRemoteCacheParams) (RemoteCache, error) {
	row := q.db.QueryRow(ctx, upsertRemoteCache,
		arg.RepoID,
		arg.CacheKey,
		arg.Status,
		arg.BlobDigest,
		arg.FetchedAt,
	)
	var i RemoteCache
	err := row.Scan(
		&i.RepoID,
		&i.CacheKey,
		&i.Status,
		&i.BlobDigest,
		&i.FetchedAt,
	)
	return i, err
}
